## hasOwnProperty e instanceof

Estas dos herramientas te permiten **inspeccionar la cadena de prototipos** en tiempo de ejecución. Son esenciales para escribir código robusto cuando trabajas con herencia.

---

## hasOwnProperty

Retorna `true` si la propiedad pertenece **directamente** al objeto (no a su cadena de prototipos):

```javascript
const proto = { heredada: true };
const obj = Object.create(proto);
obj.propia = 42;

console.log(obj.hasOwnProperty('propia'));   // true
console.log(obj.hasOwnProperty('heredada')); // false — está en el prototipo
console.log(obj.hasOwnProperty('toString')); // false — está en Object.prototype

// 'in' busca en toda la cadena
console.log('propia' in obj);   // true
console.log('heredada' in obj); // true
console.log('toString' in obj); // true
```

---

## Cuándo importa la diferencia

**Iterar solo propiedades propias:**

```javascript
const base = { metodo() {} };
const obj = Object.create(base);
obj.a = 1;
obj.b = 2;
obj.c = 3;

// for...in recorre TODA la cadena
for (const key in obj) {
  console.log(key); // a, b, c, metodo ← ¡incluye lo heredado!
}

// Con hasOwnProperty: solo las propias
for (const key in obj) {
  if (obj.hasOwnProperty(key)) {
    console.log(key); // a, b, c ✅
  }
}

// Alternativa moderna — no recorre la cadena
for (const key of Object.keys(obj)) {
  console.log(key); // a, b, c ✅
}
```

---

## Object.hasOwn() — la forma moderna

En ES2022 llegó `Object.hasOwn()`, que es más seguro porque no depende del prototipo:

```javascript
const obj = Object.create(null); // Sin prototipo
obj.x = 1;

// obj.hasOwnProperty('x') → TypeError: obj.hasOwnProperty is not a function
// (porque no tiene prototipo)

// La forma segura:
console.log(Object.hasOwn(obj, 'x')); // true ✅
```

---

## instanceof

Verifica si un objeto aparece en la cadena de prototipos de un constructor:

```javascript
function Animal(nombre) { this.nombre = nombre; }
function Perro(nombre) {
  Animal.call(this, nombre);
}
Perro.prototype = Object.create(Animal.prototype);
Perro.prototype.constructor = Perro;

const rex = new Perro('Rex');

console.log(rex instanceof Perro);    // true
console.log(rex instanceof Animal);   // true — está en la cadena
console.log(rex instanceof Object);   // true — todo es Object
console.log(rex instanceof Function); // false

// Con clases:
class Vehiculo {}
class Coche extends Vehiculo {}

const c = new Coche();
console.log(c instanceof Coche);    // true
console.log(c instanceof Vehiculo); // true
```

---

## Cómo funciona instanceof internamente

`obj instanceof Constructor` comprueba si `Constructor.prototype` aparece en la cadena de `obj`:

```javascript
// Equivalente manual de instanceof
function esInstancia(obj, Constructor) {
  let proto = Object.getPrototypeOf(obj);
  while (proto !== null) {
    if (proto === Constructor.prototype) return true;
    proto = Object.getPrototypeOf(proto);
  }
  return false;
}

const arr = [1, 2, 3];
console.log(esInstancia(arr, Array));  // true
console.log(esInstancia(arr, Object)); // true
console.log(esInstancia(arr, Map));    // false
```

---

## Resumen de herramientas de inspección

| Herramienta | ¿Qué verifica? |
|-------------|----------------|
| `obj.hasOwnProperty(key)` | Propiedad propia del objeto |
| `Object.hasOwn(obj, key)` | Igual pero seguro con `Object.create(null)` |
| `key in obj` | Propiedad en objeto O cadena |
| `obj instanceof Constructor` | Prototipo en la cadena |
| `Object.keys(obj)` | Solo claves propias enumerables |
| `Object.getPrototypeOf(obj)` | El prototipo directo del objeto |

examples.code:
// Clonar solo propiedades propias
function clonarPropio(obj) {
  const clon = {};
  for (const key in obj) {
    if (Object.hasOwn(obj, key)) {
      clon[key] = obj[key];
    }
  }
  return clon;
}

const proto = { metodo() {}, tipo: 'base' };
const original = Object.create(proto);
original.nombre = 'Ana';
original.edad = 30;

const clon = clonarPropio(original);
console.log(clon); // { nombre: 'Ana', edad: 30 }
console.log('tipo' in clon);   // false — no se copió lo heredado
console.log('nombre' in clon); // true

// Función polimórfica con instanceof
function procesarEntrada(entrada) {
  if (entrada instanceof Array) {
    return `Array de ${entrada.length} elementos`;
  }
  if (entrada instanceof Date) {
    return `Fecha: ${entrada.toLocaleDateString()}`;
  }
  if (typeof entrada === 'string') {
    return `String: "${entrada}"`;
  }
  return `Otro: ${typeof entrada}`;
}

console.log(procesarEntrada([1, 2, 3]));      // 'Array de 3 elementos'
console.log(procesarEntrada(new Date()));     // 'Fecha: ...'
console.log(procesarEntrada('hola'));         // 'String: "hola"'
console.log(procesarEntrada(42));             // 'Otro: number'

